-- Peelr October 2026 questions: LOVERS
-- Theme: Fall: cozy, reflective, a little spooky.
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
-- Layer 1: playful, flirty, cozy fall
('lovers', 1, 'What would our perfect cozy night in look like from start to finish?', '¿Cómo sería nuestra noche acogedora perfecta en casa, de principio a fin?'),
('lovers', 1, 'Which of my sweaters have you secretly claimed as yours?', '¿Cuál de mis suéteres ya consideras tuyo en secreto?'),
('lovers', 1, 'If we went apple picking, who would eat more than we actually paid for, you or me?', 'Si fuéramos a recoger manzanas, ¿quién se comería más de lo que pagamos, tú o yo?'),
('lovers', 1, 'What fall drink do you think matches my personality?', '¿Qué bebida de otoño crees que va con mi personalidad?'),
('lovers', 1, 'What is the most romantic thing we could do around a bonfire?', '¿Qué es lo más romántico que podríamos hacer alrededor de una fogata?'),
('lovers', 1, 'Which scary movie should I never be allowed to pick again?', '¿Qué película de miedo nunca deberías dejarme elegir otra vez?'),
('lovers', 1, 'What Halloween costume do you think would make me look irresistible?', '¿Con qué disfraz de Halloween crees que me vería irresistible?'),
('lovers', 1, 'If we rented a cabin for a weekend this fall, what would you pack first?', 'Si rentáramos una cabaña un fin de semana este otoño, ¿qué empacarías primero?'),
('lovers', 1, 'What is your favorite thing about me when the weather turns cold?', '¿Qué es lo que más te gusta de mí cuando hace frío?'),
('lovers', 1, 'What fall scent reminds you of me?', '¿Qué aroma de otoño te recuerda a mí?'),
('lovers', 1, 'What fall memory from before we met do you wish you could have shared with me?', '¿Qué recuerdo de otoño de antes de conocernos desearías haber vivido conmigo?'),
('lovers', 1, 'When did you first notice you were falling for me?', '¿Cuándo notaste por primera vez que te estabas enamorando de mí?'),
('lovers', 1, 'What is something small I did recently that made you feel loved?', '¿Qué cosa pequeña hice hace poco que te hizo sentir que te quiero?'),
('lovers', 1, 'What season of your life before me do you think about most?', '¿En qué etapa de tu vida antes de mí piensas más?'),
('lovers', 1, 'What does a slow morning with me feel like to you?', '¿Cómo se siente para ti una mañana tranquila conmigo?'),
('lovers', 1, 'What fall tradition from your childhood would you love to share with me?', '¿Qué tradición de otoño de tu infancia te encantaría compartir conmigo?'),
('lovers', 1, 'What quality of mine do you appreciate more now than when we first met?', '¿Qué cualidad mía aprecias más ahora que cuando nos conocimos?'),
('lovers', 1, 'What makes you feel truly cared for on a hard day?', '¿Qué te hace sentir que de verdad te cuidan en un día difícil?'),
('lovers', 1, 'What is more romantic to you, a grand gesture or a quiet routine?', '¿Qué te parece más romántico, un gran gesto o una rutina tranquila?'),
('lovers', 1, 'What does making time for each other mean to you when life gets busy?', '¿Qué significa para ti sacar tiempo para esta relación cuando la vida se llena de cosas?'),
-- Layer 2: personal, warm
('lovers', 2, 'What fall tradition do you want us to make our own?', '¿Qué tradición de otoño quieres que hagamos nuestra?'),
('lovers', 2, 'What would you want to talk about on a long drive to see the leaves change?', '¿De qué querrías hablar en un viaje largo en carro para ver cambiar las hojas?'),
